For each $t\geq0$, and $d\in[m-1]$, define $\mathbf{v}^\text{auxiliary}(0)=\mathbf{0}$ and
	\[
	\mathbf{v}^\text{auxiliary}_d(t+dt) = \left\{
	\begin{array}{ll}
	\mathbf{v}^\text{auxiliary}_d(t)+\left(\mathbf{b}-A\mathbf{x}^\text{ideal}(t)\right)dt&\text{, if }|\Gamma^*(\mathbf{v}^\text{ideal}(t+dt))|=d\\&\text{ and } |\Gamma^*(\mathbf{v}^\text{ideal}(t))|=d,\\
	\mathbf{v}^\text{super}(t+dt)&\text{, if }|\Gamma^*(\mathbf{v}^\text{ideal}(t+dt))|=d\\&\text{ and }|\Gamma^*(\mathbf{v}^\text{ideal}(t))|\neq d,\\
	\mathbf{v}_d^\text{auxiliary}(t)&\text{, else}.
	\end{array}
	\right.
	\]
}
